}

function selName(v, fb) {
  return { select: { name: clean(v || fb) } };
}

function score(...values) {
  for (const v of values) {
    const n = Number(v);
    if (Number.isFinite(n)) return Math.max(0, Math.min(100, n));
  }
  return 0;
}

function multiNames(values, fallback) {
  let arr = [];
  if (Array.isArray(values)) arr = values;
  else if (typeof values === 'string' && values.includes(',')) arr = values.split(',');
  else if (values) arr = [values];
  else arr = [fallback];

  const seen = new Set();
  return arr
    .map(v => {
      if (typeof v === 'object' && v !== null) {
        return v.name || v.type || v.purpose || v.label || v.title || JSON.stringify(v).slice(0, 40);
      }
      return String(v);
    })
    .map(v => clean(v).slice(0, 80))
    .filter(Boolean)
    .filter(v => {
      if (seen.has(v)) return false;
      seen.add(v);
      return true;
    })
    .slice(0, 8)
    .map(name => ({ name }));
}

