function imageStrategyFrom(text) {
  const s = clean(text);

  if (/비교|전후|차이|비교표/.test(s)) return '비교형';
  if (/체크|단계|방법|순서|가이드|실천|과정|팁/.test(s)) return '가이드형';
  if (/눈물|감정|불안|후회|민망|스트레스|당황/.test(s)) return '감정형';
  if (/실패|문제|번짐|번진|화장|마스카라|고장|곰팡이|막힘|냄새|오염/.test(s)) return '문제상황형';

  return '생활형';
}

