function clean(s) {
  return String(s || '').replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();
}

function rt(s) {
  const v = clean(s);
  return v ? [{ text: { content: v.slice(0, 1900) } }] : [];
}

function title(s) {
  return [{ text: { content: clean(s || '외부 트렌드 소재').slice(0, 100) } }];
}

function sel(value, fallback) {
  return { name: clean(value || fallback) };
}

function multi(value, fallback) {
  let arr;
  if (Array.isArray(value)) arr = value;
  else if (typeof value === 'string' && value.includes(',')) arr = value.split(',');
  else arr = [value || fallback];
  const seen = new Set();
  return arr.map(v => clean(v)).filter(Boolean).filter(v => {
    if (seen.has(v)) return false;
    seen.add(v);
    return true;
  }).map(name => ({ name }));
}

function keywordsFrom(t) {
  const words = clean(t).replace(/[\[\](){}"'“”‘’.,!?|:;·]/g, ' ').split(/\s+/).filter(Boolean);
  const seen = new Set();
  const out = [];
  for (const w of words) {
    const k = w.slice(0, 80);
    if (k.length < 2 || seen.has(k)) continue;
    seen.add(k);
    out.push(k);
    if (out.length >= 6) break;
  }
  return multi(out.length ? out : ['트렌드'], '트렌드');
}

function ttlDate() {
  const d = new Date();
  d.setHours(d.getHours() + Number(cfg.trendTTLHours || 24));
  return d.toISOString();
}

function platformFor(idx) {
  const arr = Array.isArray(cfg.platforms) && cfg.platforms.length
    ? cfg.platforms
