function extractText(j) {
  return j.output?.[0]?.content?.[0]?.text ||
    j.output?.[0]?.content?.[0]?.text?.value ||
    j.choices?.[0]?.message?.content ||
    j.message?.content ||
    j.text ||
    j.content ||
    j.output ||
    '{}';
}

function parseJson(v) {
  if (typeof v === 'object' && v !== null) return v;
  const s = String(v || '{}')
    .trim()
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/```$/i, '')
    .trim();

  try {
    return JSON.parse(s);
  } catch (e) {
    return {};
  }
}

function num(v, fallback = 0) {
  const n = Number(v);
  return Number.isFinite(n) ? Math.max(0, Math.min(100, n)) : fallback;
}

function label(value, allowed, fallback) {
  const v = String(value || '').trim();
  return allowed.includes(v) ? v : fallback;
}

function rt(v) {
  const s = String(v ?? '').replace(/\s+/g, ' ').trim().slice(0, 1900);
  return s ? [{ text: { content: s } }] : [];
}

function competitionLabel(score) {
  const n = num(score);
  if (n >= 70) return '높음';
  if (n >= 40) return '보통';
  return '낮음';
}

function priorityByScore(score) {
  const n = num(score);
  if (n >= 75) return '즉시생성';
  if (n >= 55) return '후보보류';
  return '폐기';
}

function profitLabel(score) {
  const n = num(score);
  if (n >= 80) return '매우높음';
  if (n >= 65) return '높음';
  if (n >= 45) return '보통';
  return '낮음';
}

const gptItems = $input.all();
const sourceItems = $items('08C_소재DB_후보저장');

const evaluated = gptItems.map((item, idx) => {
  const source = sourceItems[idx]?.json || sourceItems[0]?.json || {};
  const evaluation = parseJson(extractText(item.json || {}));

  const ctr = num(evaluation.ctr_score);
  const searchVolume = num(evaluation.search_volume_score);
  const retention = num(evaluation.retention_score);
  const adFit = num(evaluation.ad_fit_score);
  const platformFit = num(evaluation.platform_fit_score);
  const searchPersistence = num(evaluation.search_persistence_score);
  const urgency = num(evaluation.urgency_score);
  const realLife = num(evaluation.real_life_score || evaluation.human_interest_score);
  const purchaseAction = num(evaluation.purchase_action_score);
  const competitionNumeric = num(evaluation.competition_numeric_score || evaluation.competition_score);
  const aiRisk = num(evaluation.ai_mass_content_risk_score);

  let total = num(evaluation.total_score);
  if (!total) {
    total = Math.round(
      ctr * 0.15 +
      searchVolume * 0.15 +
      retention * 0.15 +
      adFit * 0.10 +
      platformFit * 0.10 +
      searchPersistence * 0.10 +
      urgency * 0.05 +
      realLife * 0.10 +
      purchaseAction * 0.10
    );
  }

  if (competitionNumeric >= 75 && retention < 55) total = Math.max(0, total - 10);
  if (aiRisk >= 75) total = Math.max(0, total - 8);

  const productionPriority = label(
    evaluation.production_priority || evaluation.production_decision,
    ['즉시생성', '후보보류', '폐기'],
    priorityByScore(total)
  );

  const normalizedEvaluation = {
    ...evaluation,
    ctr_score: ctr,
    search_volume_score: searchVolume,
    retention_score: retention,
    ad_fit_score: adFit,
    platform_fit_score: platformFit,
    search_persistence_score: searchPersistence,
    urgency_score: urgency,
    real_life_score: realLife,
    purchase_action_score: purchaseAction,
    competition_numeric_score: competitionNumeric,
    ai_mass_content_risk_score: aiRisk,
    total_score: total,
    ad_fit_label: label(evaluation.ad_fit_label, ['높음', '보통', '낮음'], profitLabel(adFit)),
    competition_label: label(evaluation.competition_label, ['낮음', '보통', '높음'], competitionLabel(competitionNumeric)),
    production_priority: productionPriority,
    expected_profitability: label(evaluation.expected_profitability, ['매우높음', '높음', '보통', '낮음'], profitLabel(adFit + purchaseAction / 2))
  };

  const sourcePageId =
    source.id ||
    source.pageId ||
    source.sourcePageId ||
    source.materialPageId ||
    source.originalMaterialPageId ||
    '';

  return {
    ...source,
    evaluation: normalizedEvaluation,
    evaluationRankScore: total,
    productionDecision: productionPriority,
    passed: productionPriority === '즉시생성',
    sourcePageId,
    materialPageId: sourcePageId,
    originalMaterialPageId: sourcePageId
  };
});

const viable = evaluated.filter(x =>
  x.productionDecision !== '폐기'
);

const pool = viable.length ? viable : evaluated;

pool.sort((a, b) => {
  const diff =
    Number(b.evaluationRankScore || 0) -
    Number(a.evaluationRankScore || 0);

  if (diff) return diff;

  return Number(b.evaluation?.retention_score || 0) -
         Number(a.evaluation?.retention_score || 0);
});

const bestId =
  (
    pool[0]?.sourcePageId ||
    pool[0]?.materialPageId ||
    pool[0]?.originalMaterialPageId ||
    pool[0]?.pageId ||
    ''
  ).toString();

return evaluated.map((x, idx) => {
  const sourcePageId =
    x.sourcePageId ||
    x.materialPageId ||
    x.originalMaterialPageId ||
    x.pageId ||
    '';

  const ev = x.evaluation || {};

  const updateBody = {
    properties: {
