      },
      "검색지속성": {
        number: x.search_persistence_score || ev.search_persistence_score || 0
      },
      "즉시성점수": {
        number: x.urgency_score || ev.urgency_score || 0
      },
      "종합점수": {
        number: x.total_score || ev.total_score || 0
      },
      "실생활연관성": {
        number: x.real_life_score || ev.real_life_score || 0
      },
      "체류유도력": {
        number: x.retention_score || ev.retention_score || 0
      },
      "구매행동연결성": {
        number: x.purchase_action_score || ev.purchase_action_score || 0
      },
      "인간성점수": {
        number: x.human_interest_score ||
                ev.human_interest_score ||
                ev.real_life_score ||
                0
      },
      "광고적합도": {
        select: {
          name: x.ad_fit_label || ev.ad_fit_label || "보통"
        }
      },
      "경쟁강도": {
        select: {
          name: x.competition_label || ev.competition_label || "보통"
        }
      },
      "생성우선순위": {
        select: {
          name: x.productionDecision || "후보보류"
        }
      },
      "예상수익성": {
        select: {
          name: x.expected_profitability || "보통"
        }
      },
      "AI판단사유": {
        rich_text: rt(
          x.ai_reason ||
          x.reason ||
          x.reject_reason ||
          ""
        )
      }
    }
  };

  return {
    json: {
      ...x,
      sourcePageId,
      materialPageId: sourcePageId,
      originalMaterialPageId: sourcePageId,
      pageId: sourcePageId,
      updateBody,
      isTopCandidate: sourcePageId.toString() === bestId,
      passed: x.productionDecision === '즉시생성'
    }
  };
});

